ALTER TABLE "AppSetting" ADD COLUMN "logoPath" TEXT NOT NULL DEFAULT '', ADD COLUMN "watermarkPath" TEXT NOT NULL DEFAULT '', ADD COLUMN "address" TEXT NOT NULL DEFAULT '', ADD COLUMN "contactEmail" TEXT NOT NULL DEFAULT '', ADD COLUMN "contactPhone" TEXT NOT NULL DEFAULT '', ADD COLUMN "gradingScale" JSONB NOT NULL DEFAULT '[{"grade":"A","min":70,"remark":"Excellent"},{"grade":"B","min":60,"remark":"Very good"},{"grade":"C","min":50,"remark":"Good"},{"grade":"D","min":45,"remark":"Fair"},{"grade":"E","min":40,"remark":"Pass"},{"grade":"F","min":0,"remark":"Needs improvement"}]', ADD COLUMN "passingMark" INTEGER NOT NULL DEFAULT 40, ADD COLUMN "syncEnabled" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "activeSessionId" TEXT, ADD COLUMN "activeTermId" TEXT, ADD COLUMN "principalName" TEXT NOT NULL DEFAULT '', ADD COLUMN "principalSignaturePath" TEXT NOT NULL DEFAULT '';
ALTER TABLE "Exam" ADD COLUMN "subjectId" TEXT, ADD COLUMN "termId" TEXT, ADD COLUMN "timed" BOOLEAN NOT NULL DEFAULT true, ADD COLUMN "autoSubmit" BOOLEAN NOT NULL DEFAULT true, ADD COLUMN "assessmentLabel" TEXT NOT NULL DEFAULT 'FINAL_EXAM';
ALTER TABLE "Question" ADD COLUMN "type" TEXT NOT NULL DEFAULT 'MCQ', ADD COLUMN "correctText" TEXT;
ALTER TABLE "StudentResponse" ALTER COLUMN "optionId" DROP NOT NULL, ADD COLUMN "responseText" TEXT, ADD COLUMN "manualScore" INTEGER, ADD COLUMN "feedback" TEXT NOT NULL DEFAULT '';

CREATE TABLE "AcademicSession" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AcademicSession_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AcademicSession_name_key" ON "AcademicSession"("name");
CREATE TABLE "Term" ("id" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"name" TEXT NOT NULL,"position" INTEGER NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "Term_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Term_sessionId_name_key" ON "Term"("sessionId","name");
CREATE TABLE "Subject" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"core" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "Subject_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Subject_code_key" ON "Subject"("code"); CREATE UNIQUE INDEX "Subject_name_key" ON "Subject"("name");
CREATE TABLE "ClassSubject" ("id" TEXT NOT NULL,"classId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"teacherId" TEXT,CONSTRAINT "ClassSubject_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ClassSubject_classId_subjectId_key" ON "ClassSubject"("classId","subjectId"); CREATE INDEX "ClassSubject_teacherId_idx" ON "ClassSubject"("teacherId");
CREATE TABLE "StaffProfile" ("userId" TEXT NOT NULL,"employeeNumber" TEXT NOT NULL,"phone" TEXT NOT NULL DEFAULT '',"address" TEXT NOT NULL DEFAULT '',"qualifications" JSONB NOT NULL,"salaryMinor" INTEGER,"payrollStatus" TEXT NOT NULL DEFAULT 'NOT_CONFIGURED',"hiredAt" TIMESTAMP(3),CONSTRAINT "StaffProfile_pkey" PRIMARY KEY ("userId"));
CREATE UNIQUE INDEX "StaffProfile_employeeNumber_key" ON "StaffProfile"("employeeNumber");
CREATE TABLE "StaffClass" ("staffId" TEXT NOT NULL,"classId" TEXT NOT NULL,CONSTRAINT "StaffClass_pkey" PRIMARY KEY ("staffId","classId"));
CREATE TABLE "StoredFile" ("id" TEXT NOT NULL,"storageName" TEXT NOT NULL,"originalName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"purpose" TEXT NOT NULL,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StoredFile_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "StoredFile_storageName_key" ON "StoredFile"("storageName");
CREATE TABLE "Assignment" ("id" TEXT NOT NULL,"classSubjectId" TEXT NOT NULL,"termId" TEXT NOT NULL,"title" TEXT NOT NULL,"instructions" TEXT NOT NULL,"releaseAt" TIMESTAMP(3) NOT NULL,"dueAt" TIMESTAMP(3) NOT NULL,"maxScore" INTEGER NOT NULL,"published" BOOLEAN NOT NULL DEFAULT false,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Assignment_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Assignment_classSubjectId_termId_idx" ON "Assignment"("classSubjectId","termId");
CREATE TABLE "AssignmentAttachment" ("assignmentId" TEXT NOT NULL,"fileId" TEXT NOT NULL,CONSTRAINT "AssignmentAttachment_pkey" PRIMARY KEY ("assignmentId","fileId"));
CREATE TABLE "AssignmentSubmission" ("id" TEXT NOT NULL,"assignmentId" TEXT NOT NULL,"studentId" TEXT NOT NULL,"text" TEXT NOT NULL DEFAULT '',"submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"score" INTEGER,"feedback" TEXT NOT NULL DEFAULT '',"gradedAt" TIMESTAMP(3),"gradedById" TEXT,CONSTRAINT "AssignmentSubmission_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AssignmentSubmission_assignmentId_studentId_key" ON "AssignmentSubmission"("assignmentId","studentId");
CREATE TABLE "SubmissionFile" ("submissionId" TEXT NOT NULL,"fileId" TEXT NOT NULL,CONSTRAINT "SubmissionFile_pkey" PRIMARY KEY ("submissionId","fileId"));
CREATE TABLE "StudyMaterial" ("id" TEXT NOT NULL,"classSubjectId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"fileId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StudyMaterial_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CourseRubric" ("id" TEXT NOT NULL,"classSubjectId" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CourseRubric_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CourseRubric_classSubjectId_key" ON "CourseRubric"("classSubjectId");
CREATE TABLE "RubricComponent" ("id" TEXT NOT NULL,"rubricId" TEXT NOT NULL,"key" TEXT NOT NULL,"label" TEXT NOT NULL,"weight" INTEGER NOT NULL,CONSTRAINT "RubricComponent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "RubricComponent_rubricId_key_key" ON "RubricComponent"("rubricId","key");
CREATE TABLE "GradeEntry" ("id" TEXT NOT NULL,"studentId" TEXT NOT NULL,"classSubjectId" TEXT NOT NULL,"termId" TEXT NOT NULL,"componentKey" TEXT NOT NULL,"title" TEXT NOT NULL,"score" INTEGER NOT NULL,"maxScore" INTEGER NOT NULL,"comment" TEXT NOT NULL DEFAULT '',"teacherId" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "GradeEntry_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "GradeEntry_studentId_classSubjectId_termId_componentKey_title_key" ON "GradeEntry"("studentId","classSubjectId","termId","componentKey","title"); CREATE INDEX "GradeEntry_classSubjectId_termId_idx" ON "GradeEntry"("classSubjectId","termId");
CREATE TABLE "PromotionRule" ("id" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"sourceClassId" TEXT NOT NULL,"targetClassId" TEXT NOT NULL,"minimumAverage" INTEGER NOT NULL,"coreSubjectMinimum" INTEGER NOT NULL,"maximumFailedCore" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "PromotionRule_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PromotionRule_sessionId_sourceClassId_key" ON "PromotionRule"("sessionId","sourceClassId");
CREATE TABLE "PromotionRun" ("id" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PREVIEW',"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"appliedAt" TIMESTAMP(3),CONSTRAINT "PromotionRun_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PromotionDecision" ("id" TEXT NOT NULL,"runId" TEXT NOT NULL,"studentId" TEXT NOT NULL,"fromClassId" TEXT NOT NULL,"toClassId" TEXT,"average" INTEGER NOT NULL,"failedCore" INTEGER NOT NULL,"outcome" TEXT NOT NULL,"reason" TEXT NOT NULL,CONSTRAINT "PromotionDecision_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PromotionDecision_runId_studentId_key" ON "PromotionDecision"("runId","studentId");
CREATE TABLE "ReportComment" ("id" TEXT NOT NULL,"studentId" TEXT NOT NULL,"termId" TEXT NOT NULL,"teacherComment" TEXT NOT NULL DEFAULT '',"principalComment" TEXT NOT NULL DEFAULT '',"authorId" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ReportComment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ReportComment_studentId_termId_key" ON "ReportComment"("studentId","termId");

ALTER TABLE "Exam" ADD CONSTRAINT "Exam_termId_fkey" FOREIGN KEY ("termId") REFERENCES "Term"("id") ON DELETE SET NULL ON UPDATE CASCADE, ADD CONSTRAINT "Exam_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id") ON DELETE SET NULL ON UPDATE CASCADE;
